from fastapi import APIRouter
from fastapi.responses import HTMLResponse
from nexora.recon.dns_recon import router as dns_router

router = APIRouter()
router.include_router(dns_router)

@router.get('/dashboard', response_class=HTMLResponse)
def dashboard():
    return HTML

HTML = r'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LinuxSec AI | Dashboard</title>
<style>
:root{color-scheme:dark;--bg:#0b1220;--panel:#142a3b;--line:#2b4b5c;--ink:#e6f7f7;--muted:#9ab8c4;--cyan:#00d9d0;--green:#35e4a0;--amber:#ffb454}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px system-ui,Arial}a{color:var(--cyan)}.layout{display:grid;grid-template-columns:230px 1fr;min-height:100vh}aside{padding:25px 18px;background:#0d1d2d;border-right:1px solid var(--line)}.brand{font-size:20px;font-weight:800;color:var(--cyan);margin-bottom:34px}.nav{display:block;padding:13px;border-radius:10px;color:var(--muted);text-decoration:none;margin:6px 0}.nav.active,.nav:hover{background:var(--panel);color:var(--ink)}main{padding:30px;max-width:1400px;width:100%;margin:auto}.heading{display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap}h1{font-size:28px;margin:0}h2{font-size:17px;margin:0 0 18px}.sub{color:var(--muted);margin-top:8px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:24px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;min-width:0}.metric{font-size:32px;font-weight:750;margin-top:8px}.label{color:var(--muted);font-size:13px}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.form{display:flex;align-items:center;gap:12px;flex-wrap:wrap}input,select{background:#081725;color:var(--ink);border:1px solid var(--line);padding:12px;border-radius:9px;min-width:170px;max-width:100%}input[type=checkbox]{min-width:0}button{border:0;border-radius:9px;padding:12px 18px;background:var(--green);color:#092021;font-weight:800;cursor:pointer}button.secondary{background:#264b5d;color:var(--ink)}button.danger{background:#783b43;color:#fff}button:disabled{opacity:.5;cursor:wait}.bar{height:16px;border-radius:8px;background:#0b1a28;overflow:hidden;display:flex;margin:16px 0}.bar span{height:100%}.legend{display:flex;gap:15px;flex-wrap:wrap;color:var(--muted);font-size:13px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}.row{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:11px 0;gap:10px}.row:last-child{border:0}.tag{border-radius:7px;padding:4px 9px;background:#123c37;color:var(--green);font-size:12px}.output{white-space:pre-wrap;overflow-wrap:anywhere;background:#091724;padding:16px;border-radius:10px;max-height:350px;overflow:auto;color:#c8e8e6;font:12px ui-monospace,monospace}.status{color:var(--muted);font-size:13px}.empty{color:var(--muted);padding:20px 0}.chartline{display:flex;align-items:center;gap:12px;margin:12px 0}.chartline label{width:70px;color:var(--muted)}.track{background:#091724;border-radius:7px;flex:1;height:17px;overflow:hidden}.fill{background:var(--cyan);height:100%;width:0;transition:width .4s}.num{width:28px;text-align:right}.notice{padding:12px;background:#09252c;border:1px solid var(--line);border-radius:10px;margin:12px 0}section[hidden]{display:none!important}iframe{width:100%;height:850px;border:0;background:var(--bg)}@media(max-width:950px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line);padding:15px}.brand{margin:0 0 8px}.nav{display:inline-block;margin:2px}main{padding:18px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.two{grid-template-columns:1fr}}@media(max-width:480px){.grid{grid-template-columns:1fr 1fr}.metric{font-size:26px}}
</style></head><body><div class="layout"><aside><div class="brand">⬡ LINUXSEC AI</div>
<a class="nav active" href="#dashboard" data-tab="dashboard">▣ Dashboard</a>
<a class="nav" href="#targets" data-tab="targets">◎ Alvos autorizados</a>
<a class="nav" href="#dns" data-tab="dns">◉ DNS Recon</a>
<a class="nav" href="#http-analyzer" data-tab="http-analyzer">⌘ Analisador HTTP</a>
<a class="nav" href="/docs">◈ API / Ferramentas</a>
<p class="sub" style="font-size:12px;margin-top:28px">Uso local • verificações em Alvos cadastrados</p></aside>
<main>
<section id="view-dashboard">
<div class="heading"><div><h1>Security Overview</h1><p class="sub">Resultados reais do Nmap, sem dados simulados.</p></div><span class="status" id="status" role="status">Nenhuma varredura nesta sessão</span></div>
<div class="grid"><div class="card"><div class="label">Hosts verificados</div><div class="metric" id="hosts">0</div></div><div class="card"><div class="label">Portas abertas</div><div class="metric" id="open">0</div></div><div class="card"><div class="label">Portas fechadas</div><div class="metric" id="closed">0</div></div><div class="card"><div class="label">Serviços identificados</div><div class="metric" id="services">0</div></div></div>
<div class="card" style="margin-bottom:16px"><h2>Executar Nmap</h2><div class="form"><label for="target">Alvo autorizado</label><select id="target" aria-label="Alvo autorizado"></select><button id="scan">Iniciar verificação</button><button class="secondary" id="manage">Gerenciar IPs</button></div><p class="status">IPs e domínios cadastrados. Para domínios, o DNS é validado novamente antes da varredura.</p></div>
<div class="two"><div class="card"><h2>Distribuição das portas</h2><div class="bar"><span id="openbar" style="background:var(--green);width:0%"></span><span id="closedbar" style="background:#476879;width:0%"></span><span id="otherbar" style="background:var(--amber);width:0%"></span></div><div class="legend"><span><i class="dot" style="background:var(--green)"></i>Abertas</span><span><i class="dot" style="background:#476879"></i>Fechadas</span><span><i class="dot" style="background:var(--amber)"></i>Outros estados</span></div><div class="empty" id="chartEmpty">Execute uma varredura para preencher o gráfico.</div></div><div class="card"><h2>Serviços por porta</h2><div id="serviceChart" class="empty">Aguardando resultados reais.</div></div></div>
<div class="two" style="margin-top:16px"><div class="card"><h2>Portas e serviços</h2><div id="ports" class="empty">Nenhum resultado ainda.</div></div><div class="card"><h2>Saída original do Nmap</h2><pre class="output" id="raw">Nenhuma varredura executada.</pre><p class="status">A saída original permanece visível para conferência. Portas abertas não comprovam vulnerabilidades.</p></div></div>
<div class="card" style="margin-top:16px"><h2>Interpretação do Ollama</h2><button class="secondary" id="analyzeNmap" disabled>Analisar último resultado com IA</button><pre class="output" id="aiOutput">Execute uma varredura antes de solicitar a análise.</pre></div>
</section>
<section id="view-targets" hidden><h1>Gerenciador de Alvos</h1><p class="sub">Cadastre IPs ou domínios de servidores para os quais você possui autorização explícita. URLs http(s) sem caminhos também são aceitas.</p>
<div class="card" style="margin-top:20px"><h2>Adicionar IP ou domínio autorizado</h2><form id="targetForm" class="form"><input id="newIp" placeholder="IP, exemplo.com ou https://exemplo.com" required maxlength="253" aria-label="IP ou domínio"><input id="newLabel" placeholder="Nome do servidor (opcional)" maxlength="80" aria-label="Descrição"><label><input id="authorized" type="checkbox" required> Confirmo autorização para testar este alvo e seus IPs DNS</label><button type="submit">Adicionar alvo</button></form><p class="status" id="targetStatus" role="status"></p></div>
<div class="card" style="margin-top:16px"><h2>Alvos cadastrados</h2><div id="targetList">Carregando...</div></div><div class="notice">O cadastro autoriza o LinuxSec AI a executar verificações manuais neste IP. Não habilita agendamento nem monitoramento contínuo.</div></section>
<section id="view-dns" hidden>
<h1>DNS Recon</h1><p class="sub">Consultas DNS reais de domínios previamente cadastrados no escopo autorizado.</p>
<div class="card" style="margin-top:20px"><h2>Consultar registros DNS</h2>
<div class="form"><label for="dnsTarget">Domínio autorizado</label><select id="dnsTarget"></select><button id="dnsScan">Consultar DNS</button></div>
<p class="status" id="dnsStatus" role="status">Selecione um domínio cadastrado.</p></div>
<div class="card" style="margin-top:16px"><h2>Registros A, AAAA, MX, NS, TXT e CNAME</h2>
<div id="dnsResults" class="empty">Nenhuma consulta executada.</div></div>
<div class="notice">DNS Recon não executa Nmap, enumeração de subdomínios ou testes de exploração. As respostas podem variar conforme o resolvedor e o TTL.</div>
</section>
<section id="view-http-analyzer" hidden><h1>Analisador HTTP</h1><p class="sub">Requisições e respostas HTTP, com análise opcional do Ollama.</p><div class="card" style="padding:0;overflow:hidden;margin-top:16px"><iframe id="httpAnalyzerFrame" title="Analisador HTTP" data-src="/analyzer"></iframe></div></section>
</main></div>
<script>
const $=id=>document.getElementById(id);let lastScan=null;
function showTab(tab){if(!['dashboard','targets','dns','http-analyzer'].includes(tab))tab='dashboard';for(const name of ['dashboard','targets','dns','http-analyzer'])$('view-'+name).hidden=name!==tab;document.querySelectorAll('[data-tab]').forEach(a=>a.classList.toggle('active',a.dataset.tab===tab));if(tab==='http-analyzer'&&!$('httpAnalyzerFrame').src)$('httpAnalyzerFrame').src=$('httpAnalyzerFrame').dataset.src;if(tab==='targets'||tab==='dns')loadTargets();}
document.querySelectorAll('[data-tab]').forEach(a=>a.addEventListener('click',()=>showTab(a.dataset.tab)));
window.addEventListener('hashchange',()=>showTab(location.hash.slice(1)));showTab(location.hash.slice(1));
$('manage').addEventListener('click',()=>{location.hash='targets';showTab('targets')});
async function api(url,options){const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Erro HTTP '+response.status);return data;}
async function loadTargets(){try{const data=await api('/tools/targets');const select=$('target');const previous=select.value;select.replaceChildren();$('dnsTarget').replaceChildren();$('targetList').replaceChildren();for(const item of data.targets){const option=document.createElement('option');option.value=item.ip;option.textContent=item.label?item.label+' — '+item.ip:item.ip;select.append(option);if(item.ip.includes('.') && !/^[0-9.]+$/.test(item.ip) || item.ip.includes(':')===false && /[a-z]/i.test(item.ip)){const dnsOption=document.createElement('option');dnsOption.value=item.ip;dnsOption.textContent=item.label?item.label+' — '+item.ip:item.ip;$('dnsTarget').append(dnsOption)}const row=document.createElement('div');row.className='row';const name=document.createElement('span');name.textContent=(item.label?item.label+' — ':'')+item.ip+(item.resolved_ips&&item.resolved_ips.length?' → '+item.resolved_ips.join(', '):'');row.append(name);if(item.ip!=='127.0.0.1'){const del=document.createElement('button');del.className='danger';del.textContent='Excluir';del.addEventListener('click',async()=>{if(!confirm('Remover '+item.ip+' do escopo autorizado?'))return;try{await api('/tools/targets/'+encodeURIComponent(item.ip),{method:'DELETE'});await loadTargets()}catch(e){$('targetStatus').textContent=e.message}});row.append(del)}$('targetList').append(row)}if([...select.options].some(o=>o.value===previous))select.value=previous;if(!data.targets.length)$('targetList').textContent='Nenhum IP cadastrado.';if(!$('dnsTarget').options.length)$('dnsStatus').textContent='Cadastre um domínio em Alvos autorizados para usar DNS Recon.'}catch(e){$('targetStatus').textContent=e.message;}}
$('targetForm').addEventListener('submit',async event=>{event.preventDefault();$('targetStatus').textContent='Salvando...';try{await api('/tools/targets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ip:$('newIp').value.trim(),label:$('newLabel').value.trim(),authorization_confirmed:$('authorized').checked})});$('targetStatus').textContent='Alvo cadastrado com sucesso.';$('newIp').value='';$('newLabel').value='';$('authorized').checked=false;await loadTargets()}catch(e){$('targetStatus').textContent=e.message}});
function parseNmap(raw){const rows=[];for(const line of raw.split(/\r?\n/)){const m=line.match(/^(\d+)\/(tcp|udp)\s+(open|closed|filtered|open\|filtered|closed\|filtered|unfiltered)\s+(\S+)(?:\s+(.*))?$/);if(m)rows.push({port:m[1],protocol:m[2],state:m[3],service:m[4],version:m[5]||''})}return rows}
function render(data){const raw=data.stdout||'';const rows=parseNmap(raw);const open=rows.filter(r=>r.state==='open');const closed=rows.filter(r=>r.state==='closed');const other=rows.length-open.length-closed.length;const total=rows.length||1;$('hosts').textContent=data.exit_code===0?'1':'0';$('open').textContent=open.length;$('closed').textContent=closed.length;$('services').textContent=open.filter(r=>r.service!=='unknown').length;$('openbar').style.width=(100*open.length/total)+'%';$('closedbar').style.width=(100*closed.length/total)+'%';$('otherbar').style.width=(100*other/total)+'%';$('chartEmpty').textContent=rows.length?'Portas relatadas na saída do Nmap: '+rows.length:'Nenhuma linha de porta reconhecida.';$('ports').replaceChildren();for(const r of rows){const item=document.createElement('div');item.className='row';const left=document.createElement('span');left.textContent=r.port+'/'+r.protocol+' — '+r.service+(r.version?' ('+r.version+')':'');const right=document.createElement('span');right.className='tag';right.textContent=r.state;item.append(left,right);$('ports').append(item)}if(!rows.length)$('ports').textContent='Nenhuma porta reconhecida na saída.';$('serviceChart').replaceChildren();if(open.length){for(const r of open){const line=document.createElement('div');line.className='chartline';const label=document.createElement('label');label.textContent=r.port;const track=document.createElement('div');track.className='track';const fill=document.createElement('div');fill.className='fill';fill.style.width='100%';track.append(fill);const name=document.createElement('span');name.textContent=r.service;name.style.width='110px';line.append(label,track,name);$('serviceChart').append(line)}}else $('serviceChart').textContent='Nenhuma porta aberta identificada.';$('raw').textContent=raw+(data.stderr?'\nSTDERR:\n'+data.stderr:'');$('status').textContent='Alvo: '+data.target+(data.resolved_ip&&data.resolved_ip!==data.target?' → '+data.resolved_ip:'')+' • '+new Date().toLocaleString('pt-BR')+' • '+data.status;lastScan=data.exit_code===0?raw:null;$('analyzeNmap').disabled=!lastScan;}
$('scan').addEventListener('click',async()=>{const button=$('scan');button.disabled=true;$('status').textContent='Executando Nmap...';try{const data=await api('/tools/nmap',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target:$('target').value})});render(data)}catch(e){$('status').textContent='Erro na verificação';$('raw').textContent=e.message}finally{button.disabled=false}});
$('analyzeNmap').addEventListener('click',async()=>{if(!lastScan)return;const button=$('analyzeNmap');button.disabled=true;$('aiOutput').textContent='Consultando Ollama...';try{const data=await api('/tools/analyze-nmap',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scan_output:lastScan.slice(0,30000)})});$('aiOutput').textContent=data.analysis||'Sem resposta da IA.'}catch(e){$('aiOutput').textContent=e.message}finally{button.disabled=false}});
loadTargets();

$('dnsScan').addEventListener('click',async()=>{
  const btn=$('dnsScan');const domain=$('dnsTarget').value;
  if(!domain){$('dnsStatus').textContent='Cadastre e selecione um domínio primeiro.';return;}
  btn.disabled=true;$('dnsStatus').textContent='Consultando DNS...';
  $('dnsResults').replaceChildren();
  try{
    const data=await api('/tools/dns-recon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target:domain})});
    $('dnsStatus').textContent='Consulta concluída: '+data.target+' • '+new Date(data.queried_at).toLocaleString('pt-BR');
    for(const [type,info] of Object.entries(data.records)){
      const block=document.createElement('div');block.className='row';block.style.alignItems='flex-start';
      const title=document.createElement('strong');title.textContent=type;title.style.minWidth='75px';
      const pre=document.createElement('pre');pre.className='output';pre.style.flex='1';pre.style.margin='0';
      pre.textContent=info.records.length?info.records.join('\n'):'('+info.status+')';
      if(info.ttl!==undefined)pre.textContent+='\nTTL: '+info.ttl+'s';
      block.append(title,pre);$('dnsResults').append(block);
    }
  }catch(e){$('dnsStatus').textContent='Falha: '+e.message;}
  finally{btn.disabled=false;}
});
</script></body></html>'''
